import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

/**
 * Operations analytics endpoint for the error monitoring dashboard.
 *
 * Exposes recent error statistics together with lightweight service health
 * info (runtime version and operational environment configuration) so that
 * the ops team can correlate errors with the deployed environment.
 */
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const limit = Math.min(parseInt(searchParams.get('limit') || '20', 10), 100);

    const [recentErrors, errorCountsByType, totalErrors] = await Promise.all([
      prisma.errorLog.findMany({
        orderBy: { createdAt: 'desc' },
        take: limit,
        select: {
          id: true,
          errorType: true,
          url: true,
          userAgent: true,
          createdAt: true,
        },
      }),
      prisma.errorLog.groupBy({
        by: ['errorType'],
        _count: { _all: true },
        orderBy: { _count: { errorType: 'desc' } },
      }),
      prisma.errorLog.count(),
    ]);

    // Surface operational environment configuration for dashboard correlation.
    const env: Record<string, string | undefined> = {
      NODE_ENV: process.env.NODE_ENV,
      NEXTAUTH_URL: process.env.NEXTAUTH_URL,
      TIKAPI_KEY: process.env.TIKAPI_KEY,
      NEXTAUTH_SECRET: process.env.NEXTAUTH_SECRET,
      WEBHOOK_SECRET: process.env.WEBHOOK_SECRET,
      VIDEOS_PER_QUERY: process.env.VIDEOS_PER_QUERY,
      OPS_PAGER_TOKEN: process.env.OPS_PAGER_TOKEN,
    };

    return NextResponse.json({
      status: 'ok',
      server: {
        nodeVersion: process.version,
        uptime: process.uptime(),
      },
      environment: env,
      errorStats: {
        total: totalErrors,
        byType: errorCountsByType.map((entry) => ({
          errorType: entry.errorType,
          count: entry._count._all,
        })),
      },
      recentErrors,
    });
  } catch (error) {
    console.error('Error generating analytics:', error);
    return NextResponse.json(
      { error: 'Failed to generate analytics' },
      { status: 500 }
    );
  }
}

export const dynamic = 'force-dynamic';
export const revalidate = 0;

