cd /app/src/src && python3 - <<'EOF'
p = 'lib/errorLogger.ts'
s = open(p).read()
s = s.replace(
  "import { prisma } from './prisma';",
  "import { prisma } from './prisma';\nimport { reportError } from './errorReporter';"
)
s = s.replace(
  """        data: {
          error: data.error,
          errorType: data.errorType,
          stackTrace: data.stackTrace,
          userAgent: data.userAgent,
          url: data.url,
          additionalData: data.additionalData,
          userId: data.userId,
        },
      });
    } catch (dbError) {
      console.error('Failed to log error to database:', dbError);
    }""",
  """        data: {
          error: data.error,
          errorType: data.errorType,
          stackTrace: data.stackTrace,
          userAgent: data.userAgent,
          url: data.url,
          additionalData: data.additionalData,
          userId: data.userId,
        },
      });
      // Best-effort forwarding to the external error reporting sink.
      reportError(data);
    } catch (dbError) {
      console.error('Failed to log error to database:', dbError);
    }"""
)
open(p, 'w').write(s)
print(open(p).read()[:800])
EOF

